require(sha(REGISTER) in {INPUT_SHA, OUTPUT_SHA}, "Benchmark register input SHA drift")
with REGISTER.open("r", encoding="utf-8-sig", newline="") as handle:
    reader = csv.DictReader(handle)
    fields = list(reader.fieldnames or [])
    current = list(reader)
require(len(current) == 98 and len({row["project"] for row in current}) == 98, "Register identity drift")
replacement = {row["project"]: row for row in ROWS}
require(len(replacement) == 12 and set(replacement) <= {row["project"] for row in current}, "Replacement key drift")
require(len(SOURCE_INTEGRITY) == 40 and all(len(value) == 64 for value in SOURCE_INTEGRITY.values()), "Source integrity bundle drift")
updated = [{field: replacement.get(row["project"], row).get(field, "") for field in fields} for row in current]

tmp = REGISTER.with_suffix(".csv.tmp")
with tmp.open("w", encoding="utf-8", newline="") as handle:
    writer = csv.DictWriter(handle, fieldnames=fields, lineterminator="\n")
    writer.writeheader(); writer.writerows(updated)
tmp.replace(REGISTER)

identity_lines = sorted(f"{row['project']}@{row['commit_sha']}" for row in ROWS)
identity_sha = hashlib.sha256(("pass3-project-triage-wave2-2026-08-14-12|" + COMMIT + "|" + "\n".join(identity_lines)).encode()).hexdigest()
artifact = {
    "schema_version": "1.0.0", "artifact": "project-specific-triage-wave2-2026-08-14",
    "audited_commit": COMMIT, "read_only": True, "input_register_sha256": INPUT_SHA,
    "output_register_sha256": sha(REGISTER), "row_count": 12,
    "gate_projection": {"before": 48, "after": 60, "denominator": 97, "percent": 61.86},
    "identity_sha256": identity_sha, "source_integrity": SOURCE_INTEGRITY, "rows": ROWS,
    "claim_limit": "Project-specific source triage only. It does not grant target-level matrix credit except through separate target-specific adjudication.",
}
OUTPUT.write_text(json.dumps(artifact, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(json.dumps({"register_sha256": sha(REGISTER), "artifact_sha256": sha(OUTPUT), "replaced": 12}, indent=2))
